            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");var tables=PracticeReinforcementTables.Load(programs);byte[] map=File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN"));Func<uint,int,PracticeReinforcementClockState> create=(phase,pause)=>PracticeReinforcementClockState.Create(tables,programs,map,731,phase,pause);
